<?php
/**
 * The theme settings — everything meant to be changeable without an editor.
 *
 * Why the Customizer and not a settings page of its own: it shows the effect
 * in the preview straight away, WordPress supplies saving, resetting and
 * capability checks, and the values land in theme mods — in the theme, not in
 * foreign tables. A theme you can get rid of again without database access is
 * the same attitude as the programs themselves.
 *
 * Every per-language field is generated by looping over suvantra_languages().
 * A third language brings its own fields; nothing has to be done here.
 *
 * @package Suvantra
 */

if ( ! defined( 'ABSPATH' ) ) {
	exit;
}

/* --------------------------------------------------------------- Sanitizing */

/**
 * Free text with a small set of markup — a footer needs no more, and allowing
 * more would mean permitting a <script> in the foot of every single page.
 *
 * @param string $value Raw value.
 * @return string
 */
function suvantra_sanitize_html( $value ) {
	return wp_kses( (string) $value, array(
		'a'      => array( 'href' => array(), 'title' => array(), 'rel' => array(), 'target' => array() ),
		'strong' => array(),
		'em'     => array(),
		'br'     => array(),
		'span'   => array(),
	) );
}

/**
 * @param string $value Raw value.
 * @return string
 */
function suvantra_sanitize_email( $value ) {
	$value = sanitize_email( (string) $value );
	return is_email( $value ) ? $value : '';
}

/**
 * @param mixed $value Raw value.
 * @return bool
 */
function suvantra_sanitize_checkbox( $value ) {
	return (bool) $value;
}

/**
 * A number forced into its bounds — no 3000 pixel measure.
 *
 * @param mixed                $value   Raw value.
 * @param WP_Customize_Setting $setting The setting.
 * @return int
 */
function suvantra_sanitize_number( $value, $setting ) {
	$control = $setting->manager->get_control( $setting->id );
	$min     = ( $control && isset( $control->input_attrs['min'] ) ) ? (int) $control->input_attrs['min'] : 0;
	$max     = ( $control && isset( $control->input_attrs['max'] ) ) ? (int) $control->input_attrs['max'] : 9999;
	return max( $min, min( $max, (int) $value ) );
}

/**
 * Only values that actually exist in the choice list.
 *
 * @param mixed                $value   Raw value.
 * @param WP_Customize_Setting $setting The setting.
 * @return string
 */
function suvantra_sanitize_choice( $value, $setting ) {
	$control = $setting->manager->get_control( $setting->id );
	$choices = ( $control && ! empty( $control->choices ) ) ? array_keys( $control->choices ) : array();
	return in_array( $value, $choices, true ) ? $value : $setting->default;
}

/* -------------------------------------------------------------- Registration */

/**
 * @param WP_Customize_Manager $wp_customize The manager.
 * @return void
 */
function suvantra_customize_register( $wp_customize ) {

	$languages = suvantra_languages();
	$defaults  = suvantra_design_defaults();

	$wp_customize->add_panel( 'suvantra', array(
		'title'       => 'Suvantra', // A name, not a word to translate.
		'priority'    => 30,
		'description' => __( 'The settings of this theme. The links in the header and footer come from the menus under Appearance → Menus.', 'suvantra' ),
	) );

	/* ------------------------------------------------------------- Brand */

	$wp_customize->add_section( 'suvantra_brand', array(
		'title'       => __( 'Brand', 'suvantra' ),
		'panel'       => 'suvantra',
		'priority'    => 5,
		'description' => __( 'Logo, site icon (the mark in the browser tab) and header image. WordPress otherwise spreads these three over two other sections; they sit together here because they are set together. They are the same settings, with the same cropper.', 'suvantra' ),
	) );

	/* WordPress registers these controls itself. Rather than putting our own
	   next to them, they are moved: same setting, same cropper, same hints. */
	foreach ( array( 'custom_logo', 'site_icon', 'header_image' ) as $inherited ) {
		$control = $wp_customize->get_control( $inherited );
		if ( $control ) {
			$control->section  = 'suvantra_brand';
			$control->priority = 10;
		}
	}

	$wp_customize->add_setting( 'suvantra_header_image_where', array(
		'default'           => 'all',
		'sanitize_callback' => 'suvantra_sanitize_choice',
		'transport'         => 'refresh',
	) );
	$wp_customize->add_control( 'suvantra_header_image_where', array(
		'label'       => __( 'Show header image', 'suvantra' ),
		'description' => __( 'Without an uploaded image nothing happens here — the pages then look exactly as they do now.', 'suvantra' ),
		'section'     => 'suvantra_brand',
		'type'        => 'radio',
		'choices'     => array(
			'all'  => __( 'On all pages', 'suvantra' ),
			'home' => __( 'On the front pages only', 'suvantra' ),
		),
	) );

	/* ----------------------------------------------------------- Product */

	$wp_customize->add_section( 'suvantra_product', array(
		'title'       => __( 'Product', 'suvantra' ),
		'panel'       => 'suvantra',
		'priority'    => 10,
		'description' => __( 'Applies to every product page in every language. The page content uses the placeholders %STORE_URL% and %DOWNLOAD_URL% for them.', 'suvantra' ),
	) );

	$wp_customize->add_setting( 'suvantra_store_url', array(
		'default'           => '',
		'sanitize_callback' => 'esc_url_raw',
		'transport'         => 'refresh',
	) );
	$wp_customize->add_control( 'suvantra_store_url', array(
		'label'       => __( 'Microsoft Store address', 'suvantra' ),
		'description' => __( 'Once the app is published. While the field is empty the button leads nowhere.', 'suvantra' ),
		'section'     => 'suvantra_product',
		'type'        => 'url',
		'input_attrs' => array( 'placeholder' => 'https://apps.microsoft.com/detail/...' ),
	) );

	$wp_customize->add_setting( 'suvantra_download_url', array(
		'default'           => '',
		'sanitize_callback' => 'esc_url_raw',
		'transport'         => 'refresh',
	) );
	$wp_customize->add_control( 'suvantra_download_url', array(
		'label'       => __( 'Direct download address', 'suvantra' ),
		'description' => __( 'The installer alongside the Store. Placeholder in the page content: %DOWNLOAD_URL%.', 'suvantra' ),
		'section'     => 'suvantra_product',
		'type'        => 'url',
		'input_attrs' => array( 'placeholder' => 'https://suvantra.eu/download/...' ),
	) );

	/* ------------------------------------------------------------ Header */

	$wp_customize->add_section( 'suvantra_header', array(
		'title'       => __( 'Header', 'suvantra' ),
		'panel'       => 'suvantra',
		'priority'    => 15,
		'description' => __( 'The logo is in the Brand section. The links come from the "Main navigation" menu of each language.', 'suvantra' ),
	) );

	$wp_customize->add_setting( 'suvantra_header_layout', array(
		'default'           => 'left',
		'sanitize_callback' => 'suvantra_sanitize_choice',
		'transport'         => 'refresh',
	) );
	$wp_customize->add_control( 'suvantra_header_layout', array(
		'label'       => __( 'Arrangement', 'suvantra' ),
		'description' => __( 'Where the brand, the navigation and the language switch sit. On narrow devices the bar wraps anyway — every arrangement looks the same there.', 'suvantra' ),
		'section'     => 'suvantra_header',
		'type'        => 'radio',
		'choices'     => array(
			'left'     => __( 'Brand left, navigation right', 'suvantra' ),
			'inline'   => __( 'Brand left, navigation next to it', 'suvantra' ),
			'centre'   => __( 'Brand centred, navigation below', 'suvantra' ),
			'mirrored' => __( 'Navigation left, brand right', 'suvantra' ),
