	$wp_customize->add_setting( 'suvantra_header_sticky', array(
		'default'           => true,
		'sanitize_callback' => 'suvantra_sanitize_checkbox',
		'transport'         => 'refresh',
	) );
	$wp_customize->add_control( 'suvantra_header_sticky', array(
		'label'       => __( 'Keep the header bar in view', 'suvantra' ),
		'description' => __( 'It stays at the top while scrolling, slightly translucent. Off means it scrolls away with the content. On long legal texts keeping it is kinder, because the way back stays within reach.', 'suvantra' ),
		'section'     => 'suvantra_header',
		'type'        => 'checkbox',
	) );

	$wp_customize->add_setting( 'suvantra_header_height', array(
		'default'           => $defaults['suvantra_header_height'],
		'sanitize_callback' => 'suvantra_sanitize_number',
		'transport'         => 'refresh',
	) );
	$wp_customize->add_control( 'suvantra_header_height', array(
		'label'       => __( 'Header bar height', 'suvantra' ),
		'description' => __( 'In pixels, 66 by default. Does not apply to the centred arrangement — that one follows its contents — nor to narrow devices.', 'suvantra' ),
		'section'     => 'suvantra_header',
		'type'        => 'number',
		'input_attrs' => array( 'min' => 52, 'max' => 104, 'step' => 2 ),
	) );

	$wp_customize->add_setting( 'suvantra_header_rule', array(
		'default'           => true,
		'sanitize_callback' => 'suvantra_sanitize_checkbox',
		'transport'         => 'refresh',
	) );
	$wp_customize->add_control( 'suvantra_header_rule', array(
		'label'       => __( 'Rule below the header bar', 'suvantra' ),
		'description' => __( 'Without it the sticky bar blurs into the content below as soon as both share a colour.', 'suvantra' ),
		'section'     => 'suvantra_header',
		'type'        => 'checkbox',
	) );

	$wp_customize->add_setting( 'suvantra_language_switcher', array(
		'default'           => true,
		'sanitize_callback' => 'suvantra_sanitize_checkbox',
		'transport'         => 'refresh',
	) );
	$wp_customize->add_control( 'suvantra_language_switcher', array(
		'label'       => __( 'Show the language switch', 'suvantra' ),
		'description' => __( 'It points at the counterpart of the current page, not merely at the other front page. From three languages on it turns into a list by itself.', 'suvantra' ),
		'section'     => 'suvantra_header',
		'type'        => 'checkbox',
	) );

	/* ------------------------------------------------------------ Footer */

	$wp_customize->add_section( 'suvantra_footer', array(
		'title'       => __( 'Footer', 'suvantra' ),
		'panel'       => 'suvantra',
		'priority'    => 20,
		'description' => __( 'Further links do not belong here but in the "Footer" menu of each language — there they can be sorted, nested and pointed outwards. Privacy and imprint are appended by the theme should they be missing from the menu.', 'suvantra' ),
	) );

	$wp_customize->add_setting( 'suvantra_footer_legal_auto', array(
		'default'           => false,
		'sanitize_callback' => 'suvantra_sanitize_checkbox',
		'transport'         => 'refresh',
	) );
	$wp_customize->add_control( 'suvantra_footer_legal_auto', array(
		'label'       => __( 'Append privacy and imprint automatically', 'suvantra' ),
		'description' => __( 'They are appended only when no menu item points at those addresses — the comparison is by address, not by label, so you may name them as you like in the menu. Switch this off and the footer shows nothing but the menu: convenient while arranging things, and your own responsibility afterwards, because an imprint has to stay reachable.', 'suvantra' ),
		'section'     => 'suvantra_footer',
		'type'        => 'checkbox',
	) );

	$wp_customize->add_setting( 'suvantra_footer_layout', array(
		'default'           => 'row',
		'sanitize_callback' => 'suvantra_sanitize_choice',
		'transport'         => 'refresh',
	) );
	$wp_customize->add_control( 'suvantra_footer_layout', array(
		'label'       => __( 'Layout', 'suvantra' ),
		'description' => __( 'Columns are worth it from roughly five links onwards. The top level menu items then become column headings and their children the links below.', 'suvantra' ),
		'section'     => 'suvantra_footer',
		'type'        => 'radio',
		'choices'     => array(
			'row'     => __( 'One row (few links)', 'suvantra' ),
			'columns' => __( 'Columns (menu with sub-items)', 'suvantra' ),
		),
	) );

	foreach ( $languages as $code => $language ) {
		$wp_customize->add_setting( 'suvantra_footer_copyright_' . $code, array(
			'default'           => '&copy; %YEAR% Suvantra',
			'sanitize_callback' => 'suvantra_sanitize_html',
			'transport'         => 'postMessage',
		) );
		$wp_customize->add_control( 'suvantra_footer_copyright_' . $code, array(
			/* translators: %s: language name, e.g. English. */
			'label'       => sprintf( __( 'Line on the left (%s)', 'suvantra' ), $language['name'] ),
			'description' => __( '%YEAR% is replaced by the current year.', 'suvantra' ),
			'section'     => 'suvantra_footer',
			'type'        => 'text',
		) );

		$wp_customize->add_setting( 'suvantra_footer_note_' . $code, array(
			'default'           => '',
			'sanitize_callback' => 'suvantra_sanitize_html',
			'transport'         => 'postMessage',
		) );
		$wp_customize->add_control( 'suvantra_footer_note_' . $code, array(
			/* translators: %s: language name, e.g. English. */
			'label'       => sprintf( __( 'Closing note (%s)', 'suvantra' ), $language['name'] ),
			'description' => __( 'A second, quieter line below. Leaving it empty hides it.', 'suvantra' ),
			'section'     => 'suvantra_footer',
			'type'        => 'textarea',
		) );
	}

	$wp_customize->add_setting( 'suvantra_footer_email', array(
		'default'           => 'support@suvantra.eu',
		'sanitize_callback' => 'suvantra_sanitize_email',
		'transport'         => 'postMessage',
	) );
	$wp_customize->add_control( 'suvantra_footer_email', array(
		'label'       => __( 'Contact address in the footer', 'suvantra' ),
		'description' => __( 'Emitted as a mailto link, with the characters obfuscated.', 'suvantra' ),
		'section'     => 'suvantra_footer',
		'type'        => 'email',
	) );

	$wp_customize->add_setting( 'suvantra_footer_email_show', array(
		'default'           => true,
		'sanitize_callback' => 'suvantra_sanitize_checkbox',
		'transport'         => 'postMessage',
	) );
	$wp_customize->add_control( 'suvantra_footer_email_show', array(
		'label'   => __( 'Show the contact address', 'suvantra' ),
		'section' => 'suvantra_footer',
		'type'    => 'checkbox',
	) );

	/* Swap the footer in the preview instead of reloading the whole page. The
	   return value is exactly what footer.php emits otherwise. */
	if ( isset( $wp_customize->selective_refresh ) ) {
		$footer_settings = array( 'suvantra_footer_email', 'suvantra_footer_email_show' );
		foreach ( array_keys( $languages ) as $code ) {
			$footer_settings[] = 'suvantra_footer_copyright_' . $code;
			$footer_settings[] = 'suvantra_footer_note_' . $code;
		}
		$wp_customize->selective_refresh->add_partial( 'suvantra_footer_partial', array(
			'selector'            => 'footer .wrap',
			'container_inclusive' => false,
			'settings'            => $footer_settings,
			'render_callback'     => 'suvantra_footer_content',
		) );
	}

	/* ------------------------------------------------------------ Design */

	$wp_customize->add_section( 'suvantra_design', array(
		'title'       => __( 'Design', 'suvantra' ),
		'panel'       => 'suvantra',
		'priority'    => 25,
		'description' => __( 'Font size, measure and dark mode. The colours are in the two sections below.', 'suvantra' ),
	) );

	$wp_customize->add_setting( 'suvantra_font_size', array(
		'default'           => $defaults['suvantra_font_size'],
		'sanitize_callback' => 'suvantra_sanitize_number',
		'transport'         => 'refresh',
	) );
	$wp_customize->add_control( 'suvantra_font_size', array(
		'label'       => __( 'Base font size', 'suvantra' ),
		'description' => __( 'In pixels, 17 by default. Headings and lead paragraphs are calculated from it; on narrow devices it stays one pixel smaller automatically.', 'suvantra' ),
		'section'     => 'suvantra_design',
		'type'        => 'number',
		'input_attrs' => array( 'min' => 15, 'max' => 20, 'step' => 1 ),
	) );

	$wp_customize->add_setting( 'suvantra_measure', array(
		'default'           => $defaults['suvantra_measure'],
		'sanitize_callback' => 'suvantra_sanitize_number',
		'transport'         => 'refresh',
	) );
	$wp_customize->add_control( 'suvantra_measure', array(
		'label'       => __( 'Maximum page width', 'suvantra' ),
		'description' => __( 'In pixels, 1180 by default. Affects header, footer and the sections — not the text column itself, which stays at 66 characters because longer lines read worse.', 'suvantra' ),
		'section'     => 'suvantra_design',
		'type'        => 'number',
		'input_attrs' => array( 'min' => 960, 'max' => 1440, 'step' => 20 ),
	) );

	$wp_customize->add_setting( 'suvantra_dark_mode', array(
		'default'           => true,
		'sanitize_callback' => 'suvantra_sanitize_checkbox',
		'transport'         => 'refresh',
	) );
	$wp_customize->add_control( 'suvantra_dark_mode', array(
		'label'       => __( 'Ship a dark mode', 'suvantra' ),
		'description' => __( 'The site follows the operating system setting. A program with seventeen colour schemes should not advertise on a site that knows only one — switching this off is meant for an emergency rather than for taste.', 'suvantra' ),
		'section'     => 'suvantra_design',
		'type'        => 'checkbox',
	) );

	/* ----------------------------------------------------------- Colours */

	$modes = array(
		'light' => array( __( 'Colours — light mode', 'suvantra' ), 30, __( 'The default. A value left unchanged emits nothing at all.', 'suvantra' ) ),
		'dark'  => array( __( 'Colours — dark mode', 'suvantra' ), 35, __( 'Applies when the operating system is set to dark. The same colours a shade lighter will not do — on a dark ground every colour reads stronger.', 'suvantra' ) ),
	);
	foreach ( $modes as $mode => $heading ) {
		$section = 'suvantra_colors_' . $mode;
		$wp_customize->add_section( $section, array(
			'title'       => $heading[0],
			'panel'       => 'suvantra',
			'priority'    => $heading[1],
			'description' => $heading[2] . ' ' . __( 'The text on coloured surfaces is not chosen but calculated from WCAG luminance — so the button label stays legible whatever colour sits beneath it.', 'suvantra' ),
		) );

		foreach ( suvantra_color_tokens() as $key => $token ) {
			$id = 'suvantra_color_' . $key . '_' . $mode;
			$wp_customize->add_setting( $id, array(
				'default'           => $token[ $mode ],
				'sanitize_callback' => 'sanitize_hex_color',
				'transport'         => 'refresh',
			) );
			$wp_customize->add_control( new WP_Customize_Color_Control( $wp_customize, $id, array(
				'label'       => $token['label'],
				'description' => $token['note'],
				'section'     => $section,
			) ) );
		}
