	/* ----------------------------------------------------- Head metadata */

	$wp_customize->add_section( 'suvantra_head', array(
		'title'       => __( 'Head metadata and share image', 'suvantra' ),
		'panel'       => 'suvantra',
		'priority'    => 40,
		'description' => __( 'canonical, hreflang and the Open Graph tags come from the theme, because only it recognises the language from the path. Title and description of individual pages live in the editor: the title as the page title, the description in the "Excerpt" field.', 'suvantra' ),
	) );

	$wp_customize->add_setting( 'suvantra_head_meta', array(
		'default'           => true,
		'sanitize_callback' => 'suvantra_sanitize_checkbox',
		'transport'         => 'refresh',
	) );
	$wp_customize->add_control( 'suvantra_head_meta', array(
		'label'       => __( 'Emit head metadata from the theme', 'suvantra' ),
		'description' => __( 'Switch off only if the job should go back to a plugin. While the box is ticked the matching Yoast output is suppressed so that nothing sits in the head twice.', 'suvantra' ),
		'section'     => 'suvantra_head',
		'type'        => 'checkbox',
	) );

	foreach ( $languages as $code => $language ) {
		$wp_customize->add_setting( 'suvantra_meta_description_' . $code, array(
			'default'           => '',
			'sanitize_callback' => 'sanitize_text_field',
			'transport'         => 'refresh',
		) );
		$wp_customize->add_control( 'suvantra_meta_description_' . $code, array(
			/* translators: %s: language name, e.g. English. */
			'label'       => sprintf( __( 'Default description (%s)', 'suvantra' ), $language['name'] ),
			'description' => __( 'Only for pages without an excerpt of their own. About 150 characters.', 'suvantra' ),
			'section'     => 'suvantra_head',
			'type'        => 'textarea',
		) );

		$wp_customize->add_setting( 'suvantra_share_image_' . $code, array(
			'default'           => 0,
			'sanitize_callback' => 'absint',
			'transport'         => 'refresh',
		) );
		$wp_customize->add_control( new WP_Customize_Media_Control( $wp_customize, 'suvantra_share_image_' . $code, array(
			/* translators: %s: language name, e.g. English. */
			'label'       => sprintf( __( 'Share image (%s)', 'suvantra' ), $language['name'] ),
			'description' => __( '1200×630. A fallback only — the page\'s featured image counts first, then the matching file in /assets/.', 'suvantra' ),
