}
add_action( 'customize_register', 'suvantra_customize_register' );

/*
 * No preview script of our own is needed: the partial registered above is
 * enough, WordPress loads customize-selective-refresh for it and fetches only
 * the footer while typing. None of that runs on the site itself — the promise
 * of loading nothing applies to visitors.
 */
